package model; import java.io.Serializable; public class Service implements Serializable { private static final long serialVersionUID=1L; private int serviceId,averageServiceTime; private String serviceName;
 public Service(int id,String name,int mins){serviceId=id;serviceName=name;averageServiceTime=mins;} public int getServiceId(){return serviceId;} public String getServiceName(){return serviceName;} public int getAverageServiceTime(){return averageServiceTime;} public void setServiceName(String n){serviceName=n;} public void setAverageServiceTime(int m){averageServiceTime=m;} public void displayService(){System.out.printf("%-5d %-30s %d min%n",serviceId,serviceName,averageServiceTime);} }
